) AS seed(code, field_code, subfield_code, name_en, name_ar, display_order, is_active, onet_soc_code, source, arabic_review_required, source_url)
JOIN categories category ON category.code = seed.field_code
JOIN subcategories subcategory ON subcategory.code = seed.subfield_code
ON CONFLICT (code) DO UPDATE SET
  category_id = EXCLUDED.category_id,
  primary_subcategory_id = EXCLUDED.primary_subcategory_id,
  name_en = EXCLUDED.name_en,
  name_ar = EXCLUDED.name_ar,
  display_order = EXCLUDED.display_order,
  is_active = EXCLUDED.is_active,
  onet_soc_code = EXCLUDED.onet_soc_code,
